using json=nlohmann::json;
using V=glm::vec2;
constexpr int SW=640,SH=360,T=16;
const glm::vec4 WHITE(1),CYAN(.37f,.96f,.85f,1),PINK(1,.32f,.58f,1),MUTED(.55f,.66f,.75f,1),DARK(.035f,.055f,.10f,.96f);
std::filesystem::path assets="assets";
json readJSON(const std::string& name){std::ifstream f(assets/name);if(!f)throw std::runtime_error("Missing assets/"+name);return json::parse(f);}
float dist(V a,V b){return glm::length(a-b);} V unit(V p){float n=glm::length(p);return n>.001f?p/n:V(0);}
bool inside(V p,float x,float y,float w,float h){return p.x>=x&&p.y>=y&&p.x<x+w&&p.y<y+h;}
struct Box{float x,y,w,h;bool contains(V p,float pad=0)const{return inside(p,x-pad,y-pad,w+pad*2,h+pad*2);}};
struct Texture{GLuint id=0;int w=1,h=1;};
struct Vertex{float x,y,u,v,r,g,b,a;};
GLuint shader(GLenum type,const char* src){GLuint s=glCreateShader(type);glShaderSource(s,1,&src,nullptr);glCompileShader(s);int ok;glGetShaderiv(s,GL_COMPILE_STATUS,&ok);if(!ok){char log[4096];glGetShaderInfoLog(s,4096,nullptr,log);throw std::runtime_error(log);}return s;}
GLuint program(const char* vs,const char* fs){GLuint p=glCreateProgram(),a=shader(GL_VERTEX_SHADER,vs),b=shader(GL_FRAGMENT_SHADER,fs);glAttachShader(p,a);glAttachShader(p,b);glLinkProgram(p);int ok;glGetProgramiv(p,GL_LINK_STATUS,&ok);glDeleteShader(a);glDeleteShader(b);if(!ok){char log[4096];glGetProgramInfoLog(p,4096,nullptr,log);throw std::runtime_error(std::string("Shader link failed: ")+log);}return p;}
std::string shaderFile(const std::string& name){auto path=assets/"shaders"/name;std::ifstream file(path);if(!file)throw std::runtime_error("Missing shader: "+path.string());std::ostringstream out;out<<file.rdbuf();return out.str();}
GLuint fileProgram(const std::string& vertex,const std::string& fragment){auto a=shaderFile(vertex),b=shaderFile(fragment);try{return program(a.c_str(),b.c_str());}catch(const std::exception& e){throw std::runtime_error(vertex+" / "+fragment+": "+e.what());}}
Texture loadTex(const std::filesystem::path& path){Texture t;int c;auto p=stbi_load(path.string().c_str(),&t.w,&t.h,&c,4);if(!p)throw std::runtime_error("Texture: "+path.string());glGenTextures(1,&t.id);glBindTexture(GL_TEXTURE_2D,t.id);glTexImage2D(GL_TEXTURE_2D,0,GL_RGBA8,t.w,t.h,0,GL_RGBA,GL_UNSIGNED_BYTE,p);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,GL_NEAREST);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,GL_NEAREST);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_S,GL_CLAMP_TO_EDGE);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_T,GL_CLAMP_TO_EDGE);stbi_image_free(p);return t;}
std::vector<int> utf8(const std::string& s){std::vector<int> out;for(size_t i=0;i<s.size();){unsigned char c=s[i++];int cp=c,n=0;if(c>=240){cp=c&7;n=3;}else if(c>=224){cp=c&15;n=2;}else if(c>=192){cp=c&31;n=1;}while(n--&&i<s.size())cp=(cp<<6)|(s[i++]&63);out.push_back(cp);}return out;}
std::string prefixUTF8(const std::string& str,size_t count){size_t n=0;for(size_t i=0;i<str.size();i++)if((static_cast<unsigned char>(str[i])&0xc0)!=0x80){if(n++>=count)return str.substr(0,i);}return str;}
std::string wrapText(const std::string& str,int columns){std::istringstream input(str);std::string line,result;while(std::getline(input,line)){std::istringstream words(line);std::string word;int used=0;while(words>>word){int len=(int)utf8(word).size();if(used&&used+1+len>columns){result+='\n';used=0;}if(used){result+=' ';used++;}result+=word;used+=len;}result+='\n';}if(!result.empty())result.pop_back();return result;}
struct Lamp { V pos; float radius=115; bool flicker=true; bool emergency=false; };
struct Renderer{
 GLuint prog,post,vao,vbo,fbo;Texture white,tiles,people,font,menu,scene,fog,portraits,biologist;std::vector<Vertex> verts;GLuint current=0;float viewScale=1;glm::vec4 occupiedRoom=glm::vec4(0);std::map<int,int> glyph;
 Renderer(){
  prog=fileProgram("sprite.vert","sprite.frag");post=fileProgram("sprite.vert","lighting.frag");
  glGenVertexArrays(1,&vao);glGenBuffers(1,&vbo);glBindVertexArray(vao);glBindBuffer(GL_ARRAY_BUFFER,vbo);glBufferData(GL_ARRAY_BUFFER,sizeof(Vertex)*100000,nullptr,GL_STREAM_DRAW);
  for(int i=0;i<3;i++){glEnableVertexAttribArray(i);glVertexAttribPointer(i,i==2?4:2,GL_FLOAT,GL_FALSE,sizeof(Vertex),(void*)(size_t)(i==0?0:i==1?8:16));}
  glGenTextures(1,&white.id);glBindTexture(GL_TEXTURE_2D,white.id);unsigned char v[4]={255,255,255,255};glTexImage2D(GL_TEXTURE_2D,0,GL_RGBA8,1,1,0,GL_RGBA,GL_UNSIGNED_BYTE,v);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,GL_NEAREST);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,GL_NEAREST);
  if(std::filesystem::exists(assets/"biologist-v06.png"))biologist=loadTex(assets/"biologist-v06.png");if(std::filesystem::exists(assets/"portraits-v04.png"))portraits=loadTex(assets/"portraits-v04.png");tiles=loadTex(assets/"tiles.png");people=loadTex(assets/"people.png");font=loadTex(assets/"font.png");if(std::filesystem::exists(assets/"menu.png"))menu=loadTex(assets/"menu.png");
  auto chars=readJSON("font.json");for(int i=0;i<(int)chars.size();i++)glyph[chars[i].get<int>()]=i;
  fog.w=160;fog.h=90;glGenTextures(1,&fog.id);glBindTexture(GL_TEXTURE_2D,fog.id);std::vector<unsigned char> initialFog(160*90,255);glTexImage2D(GL_TEXTURE_2D,0,GL_R8,160,90,0,GL_RED,GL_UNSIGNED_BYTE,initialFog.data());glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,GL_LINEAR);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,GL_LINEAR);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_S,GL_CLAMP_TO_EDGE);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_T,GL_CLAMP_TO_EDGE);
  glGenTextures(1,&scene.id);scene.w=SW;scene.h=SH;glBindTexture(GL_TEXTURE_2D,scene.id);glTexImage2D(GL_TEXTURE_2D,0,GL_RGBA8,SW,SH,0,GL_RGBA,GL_UNSIGNED_BYTE,nullptr);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,GL_NEAREST);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,GL_NEAREST);glGenFramebuffers(1,&fbo);glBindFramebuffer(GL_FRAMEBUFFER,fbo);glFramebufferTexture2D(GL_FRAMEBUFFER,GL_COLOR_ATTACHMENT0,GL_TEXTURE_2D,scene.id,0);if(glCheckFramebufferStatus(GL_FRAMEBUFFER)!=GL_FRAMEBUFFER_COMPLETE)throw std::runtime_error("Framebuffer incomplete");glBindFramebuffer(GL_FRAMEBUFFER,0);
 }
 void flush(){if(verts.empty())return;glBindVertexArray(vao);glBindBuffer(GL_ARRAY_BUFFER,vbo);glBufferData(GL_ARRAY_BUFFER,verts.size()*sizeof(Vertex),verts.data(),GL_STREAM_DRAW);glBindTexture(GL_TEXTURE_2D,current);glDrawArrays(GL_TRIANGLES,0,(int)verts.size());verts.clear();}
 void quad(Texture t,float x,float y,float w,float h,glm::vec4 c=WHITE,float sx=0,float sy=0,float sw=-1,float sh=-1){x=320+(x-320)*viewScale;y=180+(y-180)*viewScale;w*=viewScale;h*=viewScale;if(current!=t.id){flush();current=t.id;}if(sw<0)sw=(float)t.w;if(sh==-1)sh=(float)t.h;float u=sx/t.w,v=sy/t.h,u2=(sx+sw)/t.w,v2=(sy+sh)/t.h;Vertex a{x,y,u,v,c.r,c.g,c.b,c.a},b{x+w,y,u2,v,c.r,c.g,c.b,c.a},cc{x+w,y+h,u2,v2,c.r,c.g,c.b,c.a},d{x,y+h,u,v2,c.r,c.g,c.b,c.a};verts.insert(verts.end(),{a,b,cc,a,cc,d});}
 void box(float x,float y,float w,float h,glm::vec4 c){quad(white,x,y,w,h,c);}
 void outline(float x,float y,float w,float h,glm::vec4 c){box(x,y,w,1,c);box(x,y+h-1,w,1,c);box(x,y,1,h,c);box(x+w-1,y,1,h,c);}
 void line(V a,V b,glm::vec4 c){float n=std::max(1.f,dist(a,b));for(float i=0;i<=n;i+=1)box(a.x+(b.x-a.x)*i/n,a.y+(b.y-a.y)*i/n,1,1,c);}
 void text(std::string s,float x,float y,glm::vec4 c=WHITE,float scale=1){float start=x;for(int cp:utf8(s)){if(cp==10){y+=14*scale;x=start;continue;}int n=glyph.count(cp)?glyph[cp]:glyph['?'];quad(font,x,y,8*scale,16*scale,c,float(n%32*8),float(n/32*16),8,16);x+=8*scale;}}
 void center(std::string s,float y,glm::vec4 c=WHITE,float scale=1){text(s,(SW-utf8(s).size()*8*scale)/2,y,c,scale);}
 void tile(int id,float x,float y,glm::vec4 c=WHITE){quad(tiles,x,y,16,16,c,float(id%16*16),float(id/16*16),16,16);}
 void person(V p,int kind,int dir,int frame,glm::vec4 c=WHITE){float cw=people.w/12.f,ch=people.h/5.f;quad(people,std::round(p.x)-11,std::round(p.y)-30,22,33,c,(dir*3+frame)*cw,kind*ch,cw,ch);}
 void portrait(int who,float x,float y,float size){if(who==2&&biologist.id){quad(biologist,x,y,size,size);return;}who=std::clamp(who,0,1);if(portraits.id){float half=portraits.w/2.f;quad(portraits,x,y,size,size,WHITE,who*half,0,half,float(portraits.h));}else{box(x,y,size,size,glm::vec4(.07,.05,.14,1));person(V(x+size/2,y+size/2),who==1?2:0,0,0);}}
 void begin(){viewScale=1;glBindFramebuffer(GL_FRAMEBUFFER,fbo);glViewport(0,0,SW,SH);glClearColor(.025f,.035f,.07f,1);glClear(GL_COLOR_BUFFER_BIT);glEnable(GL_BLEND);glBlendFunc(GL_SRC_ALPHA,GL_ONE_MINUS_SRC_ALPHA);glUseProgram(prog);auto mat=glm::ortho(0.f,float(SW),float(SH),0.f);glUniformMatrix4fv(glGetUniformLocation(prog,"projection"),1,GL_FALSE,&mat[0][0]);current=0;}
 void present(int fw,int fh,float time,bool world,bool restored,bool flicker,const std::vector<Lamp>& lamps,V player){flush();glBindFramebuffer(GL_FRAMEBUFFER,0);glViewport(0,0,fw,fh);glClearColor(.012f,.018f,.035f,1);glClear(GL_COLOR_BUFFER_BIT);float scale=std::min(fw/float(SW),fh/float(SH));int w=int(SW*scale),h=int(SH*scale);glViewport((fw-w)/2,(fh-h)/2,w,h);glUseProgram(post);auto mat=glm::ortho(0.f,float(SW),float(SH),0.f);glUniformMatrix4fv(glGetUniformLocation(post,"projection"),1,GL_FALSE,&mat[0][0]);glUniform1f(glGetUniformLocation(post,"time"),time);glUniform1f(glGetUniformLocation(post,"world"),world?1.f:0.f);glUniform1f(glGetUniformLocation(post,"restored"),restored?1.f:0.f);glUniform1f(glGetUniformLocation(post,"flicker"),flicker?1.f:0.f);glUniform2f(glGetUniformLocation(post,"player"),player.x,player.y);int n=std::min(32,(int)lamps.size());glUniform1i(glGetUniformLocation(post,"lampCount"),n);if(n){std::vector<V> pp;std::vector<float> rr,ff,ee;for(int i=0;i<n;i++){pp.push_back(lamps[i].pos);rr.push_back(lamps[i].radius);ff.push_back(lamps[i].flicker?1.f:0.f);ee.push_back(lamps[i].emergency?1.f:0.f);}glUniform2fv(glGetUniformLocation(post,"lamps"),n,&pp[0].x);glUniform1fv(glGetUniformLocation(post,"lampRadius"),n,rr.data());glUniform1fv(glGetUniformLocation(post,"lampFlicker"),n,ff.data());glUniform1fv(glGetUniformLocation(post,"lampEmergency"),n,ee.data());}glUniform4fv(glGetUniformLocation(post,"occupiedRoom"),1,&occupiedRoom[0]);glUniform1i(glGetUniformLocation(post,"tex"),0);glUniform1i(glGetUniformLocation(post,"visibility"),1);glActiveTexture(GL_TEXTURE1);glBindTexture(GL_TEXTURE_2D,fog.id);glActiveTexture(GL_TEXTURE0);quad(scene,0,0,SW,SH,WHITE,0,SH,SW,-float(SH));flush();glUseProgram(prog);}
 void ui(int fw,int fh){float scale=std::min(fw/float(SW),fh/float(SH));glViewport((fw-int(SW*scale))/2,(fh-int(SH*scale))/2,int(SW*scale),int(SH*scale));glUseProgram(prog);current=0;}
};
struct Audio{
 ma_engine engine{};ma_sound music{};bool ready=false,musicReady=false,enabled=true;std::string song;std::map<std::string,ma_sound*> effects;
 Audio(){ready=ma_engine_init(nullptr,&engine)==MA_SUCCESS;}
 ~Audio(){for(auto& item:effects){ma_sound_uninit(item.second);delete item.second;}if(musicReady)ma_sound_uninit(&music);if(ready)ma_engine_uninit(&engine);}
 void play(const std::string& name,float volume=1){if(!ready||!enabled)return;auto found=effects.find(name);ma_sound* effect=nullptr;if(found==effects.end()){effect=new ma_sound{};if(ma_sound_init_from_file(&engine,(assets/name).string().c_str(),0,nullptr,nullptr,effect)!=MA_SUCCESS){delete effect;return;}effects[name]=effect;}else effect=found->second;ma_sound_stop(effect);ma_sound_seek_to_pcm_frame(effect,0);ma_sound_set_volume(effect,volume);ma_sound_start(effect);}
 void theme(bool restored,bool menu=false){std::string n=menu?"menu.wav":restored?"restored.wav":"outbreak.wav";if(song==n)return;if(musicReady){ma_sound_uninit(&music);musicReady=false;}song=n;if(ready&&ma_sound_init_from_file(&engine,(assets/n).string().c_str(),MA_SOUND_FLAG_STREAM,nullptr,nullptr,&music)==MA_SUCCESS){musicReady=true;ma_sound_set_looping(&music,MA_TRUE);ma_sound_set_volume(&music,.28f);ma_sound_start(&music);}}
 void mutter(int who,int variant){static const char* names[]={"student","teacher","biologist"};play(std::string("murmur-")+names[std::clamp(who,0,2)]+"-"+std::to_string(variant%3)+".wav",.65f);}
 void toggle(){enabled=!enabled;if(ready)ma_engine_set_volume(&engine,enabled?1.f:0.f);}
};

struct Object{int id;std::string name,type;Box b;json props;bool open=true;V pos()const{return V(b.x+b.w/2,b.y+b.h/2);}};
struct Zombie{V pos,start,face=V(1,0),goal;std::vector<V> route;int index=1,block=1,state=0;float suspicion=0,memory=0,repath=0,stun=0,patrolWait=0,phaseDelay=0,dwell=0;std::vector<V> path;};
struct Map{
 std::array<bool,257> solidFlags{},visionFlags{};int w=0,h=0;std::vector<int> floor,walls,furniture;std::vector<Box> rooms;std::vector<Object> objects;std::vector<Zombie> zombies;std::vector<Lamp> lamps;std::vector<V> papers;json cfg;
 void load(){auto j=readJSON("floor3.tmj");cfg=readJSON("config.json");if(j.value("infinite",false)||j.value("orientation",std::string(""))!="orthogonal")throw std::runtime_error("Use finite orthogonal Tiled map");w=j["width"];h=j["height"];rooms.clear();objects.clear();zombies.clear();lamps.clear();papers.clear();solidFlags.fill(false);visionFlags.fill(false);for(auto& ts:j["tilesets"])if(ts.contains("tiles"))for(auto& tile:ts["tiles"]){int id=tile["id"].get<int>()+ts["firstgid"].get<int>();if(id>=257)throw std::runtime_error("Tileset exceeds supported atlas");if(tile.contains("properties"))for(auto& prop:tile["properties"]){if(prop["name"]=="solid")solidFlags[id]=prop["value"].get<bool>();if(prop["name"]=="blocksVision")visionFlags[id]=prop["value"].get<bool>();}}
  for(auto& layer:j["layers"]){std::string n=layer["name"];if(layer["type"]=="tilelayer"&&!layer["data"].is_array())throw std::runtime_error("Use uncompressed JSON arrays in Tiled");if(n=="Floor")floor=layer["data"].get<std::vector<int>>();if(n=="Walls")walls=layer["data"].get<std::vector<int>>();if(n=="Furniture")furniture=layer["data"].get<std::vector<int>>();if(layer["type"]!="objectgroup")continue;for(auto& o:layer["objects"]){json props=json::object();if(o.contains("properties"))for(auto& p:o["properties"])props[p["name"].get<std::string>()]=p["value"];
   V p(o["x"].get<float>(),o["y"].get<float>());
   if(n=="Enemies"){Zombie z;z.pos=z.start=(glm::floor(p/float(T))+V(.5f))*float(T);z.block=props.value("block",1);z.patrolWait=z.phaseDelay=props.value("phaseDelay",0.f);z.dwell=props.value("patrolDwell",0.f);for(auto& v:o["polyline"])z.route.push_back((glm::floor((p+V(v["x"].get<float>(),v["y"].get<float>()))/float(T))+V(.5f))*float(T));z.goal=z.route[0];zombies.push_back(z);}
   else if(n=="Lighting")lamps.push_back({p,props.value("radius",115.f),props.value("flicker",true),props.value("emergency",false)});
   else if(n=="Restoration")papers.push_back(p);
   else if(o.value("type",std::string(""))=="room")rooms.push_back({p.x,p.y,o.value("width",16.f),o.value("height",16.f)});else objects.push_back({o["id"],o["name"],o["type"],{p.x,p.y,o.value("width",16.f),o.value("height",16.f)},props,props.value("open",true)});
  }}if(floor.size()!=size_t(w*h)||walls.size()!=floor.size())throw std::runtime_error("Map layer dimensions mismatch");
 }
 int cell(V p)const{int x=int(floorf(p.x/T)),y=int(floorf(p.y/T));return x<0||y<0||x>=w||y>=h?-1:y*w+x;}
 bool solid(V p,bool sight=false)const{int i=cell(p);if(i<0||floor[i]==0)return true;if(walls[i])return !sight||visionFlags[std::clamp(walls[i],0,256)];int f=std::clamp(furniture[i],0,256);return sight?visionFlags[f]:solidFlags[f];}
 bool hit(V p,float r=5)const{return solid(p+V(-r,-r))||solid(p+V(r,-r))||solid(p+V(-r,r))||solid(p+V(r,r));}
 bool ray(V a,V b,bool opaqueGlass=false)const{int n=int(dist(a,b)/3)+1;for(int i=1;i<=n;i++){V p=glm::mix(a,b,float(i)/n);int ci=cell(p);if(solid(p,true)||(opaqueGlass&&ci>=0&&walls[ci]))return false;for(auto& o:objects)if((o.type=="door"||o.type=="gate")&&!o.open&&o.b.contains(p))return false;}return true;}
 std::vector<V> path(V from,V to)const{int a=cell(from),b=cell(to);if(a<0||b<0)return {};std::vector<int> prev(w*h,-1);std::queue<int> q;q.push(a);prev[a]=a;int found=-1;
  while(!q.empty()){int c=q.front();q.pop();if(c==b){found=c;break;}int x=c%w,y=c/w;for(int n:{c-1,c+1,c-w,c+w}){if(n<0||n>=w*h||std::abs(n%w-x)+std::abs(n/w-y)!=1||prev[n]!=-1)continue;V p((n%w+.5f)*T,(n/w+.5f)*T);if(hit(p,4))continue;bool blocked=false;for(auto& o:objects)if((o.type=="door"||o.type=="gate")&&!o.open&&o.b.contains(p,3)){blocked=true;break;}if(blocked)continue;prev[n]=c;q.push(n);}}
  if(found<0)return {};std::vector<V> out;for(int c=found;c!=a;c=prev[c])out.push_back(V((c%w+.5f)*T,(c/w+.5f)*T));std::reverse(out.begin(),out.end());return out;
 }
 Object* type(std::string t){for(auto& o:objects)if(o.type==t)return &o;return nullptr;}
};
