 Object* nearest(){Object* best=nullptr;float d=36;for(auto& o:map.objects){if(o.type=="spawn"||o.type=="debris"||o.type=="hazard"||(o.type=="mopweapon"&&hasMop))continue;if(o.type!="door"&&o.type!="gate"&&!map.ray(player,o.pos()))continue;if((o.type=="keycard"&&keycard)||(o.type=="serum"&&serum))continue;float dd=dist(player,o.pos());if(o.type=="door"||o.type=="gate"){dd=dist(player,V(std::clamp(player.x,o.b.x,o.b.x+o.b.w),std::clamp(player.y,o.b.y,o.b.y+o.b.h)));}if(dd<d){d=dd;best=&o;}}return best;}
