 void throwBottle(){if(!hasPhone){notify("Бутылки в сумке, а сумка пока в локере");return;}if(bottles<=0){notify("Бутылки в сумке закончились. Двигайтесь тихо.");return;}V target=mouse+cam;V delta=target-player;float distance=std::clamp(glm::length(delta),32.f,220.f);V direction=unit(delta);if(glm::length(direction)<.1f)direction=V(1,0);Projectile p;p.start=p.pos=player+direction*9.f;p.duration=distance/265.f;p.velocity=direction*265.f;projectiles.push_back(p);bottles--;throws++;audio.play("bottle-throw.wav");}
