 float visibilityCore(V origin,bool surveillance=false)const{float radius=surveillance?230.f:flashlight?185.f:145.f;if(auto room=occupiedRoomAt(origin)){for(V corner:{V(room->x,room->y),V(room->x+room->w,room->y),V(room->x,room->y+room->h),V(room->x+room->w,room->y+room->h)})radius=std::max(radius,dist(origin,corner)+5.f);}return radius;}
