void screenshot(std::string path,int w,int h){std::vector<unsigned char> pixels(w*h*3);glPixelStorei(GL_PACK_ALIGNMENT,1);glReadPixels(0,0,w,h,GL_RGB,GL_UNSIGNED_BYTE,pixels.data());int stride=(w*3+3)&~3,size=54+stride*h;std::vector<unsigned char> bmp(size);auto u32=[&](int off,uint32_t v){for(int i=0;i<4;i++)bmp[off+i]=(v>>(i*8))&255;};bmp[0]='B';bmp[1]='M';u32(2,size);u32(10,54);u32(14,40);u32(18,w);u32(22,h);bmp[26]=1;bmp[28]=24;for(int y=0;y<h;y++)for(int x=0;x<w;x++){int a=(y*w+x)*3,b=54+y*stride+x*3;bmp[b]=pixels[a+2];bmp[b+1]=pixels[a+1];bmp[b+2]=pixels[a];}std::ofstream f(path,std::ios::binary);f.write((char*)bmp.data(),bmp.size());}
